To print the first 100 prime numbers, we can write a Python script that checks for prime numbers and keeps a count of how many primes we've found until we reach 100. Here's a simple way to do it:

```python
def is_prime(n):
    """Check if a number is a prime number."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def first_n_primes(n):
    """Generate the first n prime numbers."""
    primes = []
    candidate = 2
    while len(primes) < n:
        if is_prime(candidate):
            primes.append(candidate)
        candidate += 1
    return primes

# Print the first 100 prime numbers
print(first_n_primes(100))
```

